from early_helpers import *
from math import sin,cos,sqrt,exp,sinh,cosh,pi
b=Book('12.6',[919,920,921])
def add(n,title,st,steps,ans,parts=[],check=None):b.add(n,919 if n<=22 else 920 if n<=50 else 921,title,st,steps,ans,parts,check=check)
def graph(n,f,ur,vr,title):b.plot(n,[(f,ur,vr,title)])
add(1,('평면곡선과 주면','Plane curves and cylinders'),('(a) '+r'\(y=x^2\)'+'을 평면에서, (b) 공간에서 해석하고 (c) '+r'\(z=y^2\)'+'의 공간곡면을 설명하라.','Interpret (a) '+r'\(y=x^2\)'+' in the plane, (b) in space, and (c) the surface '+r'\(z=y^2\)'+'.'),[('(a) 평면에서는 위로 열린 포물선이다.','(a) In the plane this is a parabola opening upward.'),('(b) z가 자유이므로 포물선을 z축 방향으로 늘인 주면이다. (c) x가 자유이므로 x축 평행 생성선을 가진 포물주면이다.','(b) Free z extends the parabola parallel to the z-axis. (c) Free x gives a parabolic cylinder with generators parallel to x.')],('(a) 포물선. (b) z축 평행 포물주면. (c) x축 평행 포물주면.','(a) Parabola. (b) Parabolic cylinder parallel to z. (c) Parabolic cylinder parallel to x.'),['a','b','c'])
b.plot(1,[(lambda u,v:(u,u*u,0),(-2,2),(0,1),'(a) y=x² in R²'),(lambda u,v:(u,u*u,v),(-2,2),(-2,2),'(b) z free'),(lambda u,v:(v,u,u*u),(-2,2),(-2,2),'(c) x free')])
add(2,('지수함수의 주면','Exponential cylinders'),('(a) '+r'\(y=e^x\)'+'의 평면곡선, (b) 공간곡면, (c) '+r'\(z=e^y\)'+'의 곡면을 그려 설명하라.','Sketch and describe (a) the plane curve '+r'\(y=e^x\)'+'; (b) its surface in space; (c) '+r'\(z=e^y\)'+'.'),[('(a) 양의 y값을 가지며 증가하는 지수곡선이다.','(a) It is an increasing exponential curve with positive y.'),('(b) z가 식에 없으므로 지수곡선을 z방향으로 평행이동한다. (c) x가 없으므로 yz평면 지수곡선을 x방향으로 늘인다.','(b) z is absent, so translate the exponential curve along z. (c) x is absent, so extend the yz-plane exponential along x.')],('(a) 지수곡선. (b) z축 평행 지수주면. (c) x축 평행 지수주면.','(a) Exponential curve. (b) Exponential cylinder parallel to z. (c) Exponential cylinder parallel to x.'),['a','b','c'])
b.plot(2,[(lambda u,v:(u,exp(u),0),(-2,2),(0,1),'(a) y=exp(x)'),(lambda u,v:(u,exp(u),v),(-2,2),(-2,2),'(b) z free'),(lambda u,v:(v,u,exp(u)),(-2,2),(-2,2),'(c) x free')])
data=[
(3,r'x^2+z^2=4','y축 평행 반지름 2의 원기둥','circular cylinder of radius 2 along y',r'y=k:\ x^2+z^2=4',lambda u,v:(2*cos(u),v,2*sin(u)),(0,2*pi),(-3,3)),
(4,r'y^2+9z^2=9','x축 평행 타원기둥(반축 3,1)','elliptic cylinder along x, with semiaxes 3 and 1',r'x=k:\ y^2/9+z^2=1',lambda u,v:(v,3*cos(u),sin(u)),(0,2*pi),(-3,3)),
(5,r'x^2+y+1=0','음의 y방향 포물주면, 생성선은 z축 평행','parabolic cylinder opening toward negative y, parallel to z',r'y=-x^2-1',lambda u,v:(u,-u*u-1,v),(-2,2),(-2,2)),
(6,r'z=-\sqrt x','x=z²의 z≤0 반쪽 포물주면','the z≤0 half of the parabolic cylinder x=z²',r'x=z^2,\quad z\le0,\quad y\in\mathbb R',lambda u,v:(u*u,v,-u),(0,2),(-2,2)),
(7,r'xy=1','z축 평행 쌍곡주면','hyperbolic cylinder parallel to z',r'y=1/x,\quad x\ne0', [lambda u,v:(u,1/u,v),lambda u,v:(-u,-1/u,v)],(.25,3),(-2,2)),
(8,r'z=\sin y','x축 평행 사인 주면','sinusoidal cylinder parallel to x',r'x=k:\ z=\sin y',lambda u,v:(v,u,sin(u)),(-2*pi,2*pi),(-2,2))]
for n,f,k,e,trace,fun,ur,vr in data:
 add(n,('주면의 분류','Classifying a cylinder'),('곡면을 설명하고 그려라. '+r'\('+f+r'\).','Describe and sketch '+r'\('+f+r'\).'),fs(trace)+[('식에 없는 좌표는 자유로워 그 축에 평행한 생성선을 만든다.','The missing coordinate is free and produces generators parallel to its axis.')],(k+'.',e+'.'));graph(n,fun,ur,vr,f.replace('\\',''))
add(9,('그림에서 곡면식 찾기','Equation from a surface sketch'),('x방향으로 사인파처럼 변하고 y방향으로 동일한 단면이 반복되는 원본 주면에 가능한 식을 쓰라.','Give a possible equation for the source sinusoidal cylinder varying along x and extending unchanged along y.'),[('y방향 생성선이 직선이므로 식은 y에 의존하지 않는다.','Straight generators along y mean that y does not appear.'),(r'원점에서 양의 x방향으로 내려가는 사인파에는 \(z=-\sin x\)를 선택할 수 있다.',r'A sine wave descending from the origin in the positive x-direction can be modeled by \(z=-\sin x\).')],same(r'\[z=-\sin x\quad\text{(one possible equation)}.\]'));graph(9,lambda u,v:(u,v,-sin(u)),(-2*pi,2*pi),(-2,2),'One possible sinusoidal cylinder')
add(10,('삼차곡선의 주면','A cubic cylinder'),('원본처럼 yz평면의 S자 곡선을 x방향으로 늘인 곡면의 가능한 식을 쓰라.','Give a possible equation for the source S-shaped yz-curve extended along x.'),[('x가 자유이므로 yz평면의 단면식만 정하면 된다.','Since x is free, determine only the yz cross-section.'),(r'원점을 지나 증가하는 S자 단면의 한 예는 \(z=y^3\)이다.',r'One increasing S-shaped section through the origin is \(z=y^3\).')],same(r'\[z=y^3\quad\text{(one possible equation)}.\]'));graph(10,lambda u,v:(v,u,u**3),(-1.4,1.4),(-2,2),'z=y³')
add(11,('일엽쌍곡면과 이동','One-sheeted hyperboloids and translation'),('(a) '+r'\(x^2+y^2-z^2=1\)'+'의 자취로 형태를 설명하고 (b) '+r'\(x^2-y^2+z^2=1\)'+'과 (c) '+r'\(x^2+y^2+2y-z^2=0\)'+'으로 바꾼 효과를 설명하라.','Use traces to explain (a) '+r'\(x^2+y^2-z^2=1\)'+' and describe the changes to (b) '+r'\(x^2-y^2+z^2=1\)'+' and (c) '+r'\(x^2+y^2+2y-z^2=0\)'+'.'),fs(r'(a)\ z=k:\ x^2+y^2=1+k^2;\quad x=k:\ y^2-z^2=1-k^2;\quad y=k:\ x^2-z^2=1-k^2')+[('(a) 수평 단면은 원, 수직 단면은 쌍곡선(특정 값에서 두 직선)이다. z축 둘레에서 끊기지 않는 일엽쌍곡면이다.','(a) Horizontal traces are circles; vertical traces are hyperbolas or pairs of lines. It is a connected one-sheeted hyperboloid about z.'),('(b) 음의 제곱항이 y로 바뀌어 축이 y축이 된다.','(b) The negative square moves to y, so the axis becomes y.'),same(r'(c) \(x^2+(y+1)^2-z^2=1\).')],('(a) z축 일엽쌍곡면. (b) y축으로 회전. (c) y방향으로 -1만큼 평행이동.','(a) One-sheeted hyperboloid along z. (b) Rotate the axis to y. (c) Translate by -1 in y.'),['a','b','c']);b.plot(11,[(lambda u,v:(cosh(u)*cos(v),cosh(u)*sin(v),sinh(u)),(-1.4,1.4),(0,2*pi),'(a) axis z'),(lambda u,v:(cosh(u)*cos(v),sinh(u),cosh(u)*sin(v)),(-1.4,1.4),(0,2*pi),'(b) axis y'),(lambda u,v:(cosh(u)*cos(v),-1+cosh(u)*sin(v),sinh(u)),(-1.4,1.4),(0,2*pi),'(c) center (0,-1,0)')])
add(12,('이엽쌍곡면의 자취','Traces of a two-sheeted hyperboloid'),('(a) '+r'\(-x^2-y^2+z^2=1\)'+'의 자취를 찾아 분류하고 (b) '+r'\(x^2-y^2-z^2=1\)'+'로 바꾼 곡면을 그려라.','Find traces and classify (a) '+r'\(-x^2-y^2+z^2=1\)'+'; (b) sketch the change to '+r'\(x^2-y^2-z^2=1\)'+'.'),fs(r'z=k:\ x^2+y^2=k^2-1;\quad x=k:\ z^2-y^2=1+k^2;\quad y=k:\ z^2-x^2=1+k^2')+[('|z|<1에서는 점이 없고 z=±1에서 꼭짓점이 생긴다. 양의 제곱항이 x로 바뀌면 분리된 두 잎의 축이 x축으로 옮겨간다.','There are no points for |z|<1, with vertices at z=±1. Moving the positive square to x makes x the axis of the two sheets.')],('(a) z축 이엽쌍곡면. (b) x축 이엽쌍곡면, 꼭짓점 (±1,0,0).','(a) Two-sheeted hyperboloid along z. (b) Two-sheeted hyperboloid along x, vertices (±1,0,0).'),['a','b']);b.plot(12,[([lambda u,v:(u*cos(v),u*sin(v),sqrt(1+u*u)),lambda u,v:(u*cos(v),u*sin(v),-sqrt(1+u*u))],(0,2),(0,2*pi),'(a) axis z'),([lambda u,v:(sqrt(1+u*u),u*cos(v),u*sin(v)),lambda u,v:(-sqrt(1+u*u),u*cos(v),u*sin(v))],(0,2),(0,2*pi),'(b) axis x')])
