for n,f,trace,k,e,fun,ur,vr in rows:
 instruction=('원본 I–VIII 그림과 대응시키고 이유를 설명하라.','Match to source graphs I–VIII and explain.') if 23<=n<=30 else ('자취와 표준형으로 분류하고 그려라.','Use traces and standard form to classify and sketch.')
 add(n,('이차곡면의 분류','Classifying quadrics'),(instruction[0]+r'\('+f+r'\).',instruction[1]+r'\('+f+r'\).'),fs(trace)+[('제곱항의 부호·계수와 빠진 변수에서 축, 크기 및 단면의 종류를 판정한다.','The signs and coefficients of squared terms and any missing variable determine the axis, scale, and trace types.')],(k+'.',e+'.'));graph(n,fun,ur,vr,e)
add(31,('자취에서 곡면 복원','Reconstructing a surface from traces'),('원본의 x=k 단면은 음의 y로 열린 포물선이며 y=k 단면은 k가 -2,-1,0,1로 증가할수록 줄어들어 마지막에 점이 되는 원이다. 가능한 이차곡면을 식별하고 그려라.','The source x=k sections are parabolas opening toward negative y; y=k sections shrink through k=-2,-1,0,1, ending at a point. Identify and sketch a compatible quadric.'),fs(r'y=1-x^2-z^2;\quad x=k:\ y=1-k^2-z^2;\quad y=k:\ x^2+z^2=1-k'),('꼭짓점 (0,1,0)에서 음의 y로 열린 원포물면. '+r'\[y=1-x^2-z^2.\]','Circular paraboloid opening in negative y from (0,1,0). '+r'\[y=1-x^2-z^2.\]'));graph(31,lambda u,v:(u*cos(v),1-u*u,u*sin(v)),(0,2),(0,2*pi),'y=1-x²-z²')
add(32,('타원·쌍곡선 자취 복원','Reconstructing elliptical and hyperbolic traces'),('원본의 x=k 단면은 |k|가 증가하면 커지는 타원이고, z=k 단면은 k=0에서 y방향 쌍곡선, k=1에서 두 직선, k=2에서 x방향 쌍곡선이다. 가능한 곡면을 찾고 그려라.','Source x=k traces are expanding ellipses as |k| grows. The z=k traces open along y at k=0, become two lines at k=1, and open along x at k=2. Identify and sketch a compatible surface.'),fs(r'y^2+z^2-x^2=1;\quad x=k:\ y^2+z^2=1+k^2;\quad z=k:\ y^2-x^2=1-k^2'),('x축 일엽쌍곡면의 한 예. '+r'\[y^2+z^2-x^2=1.\]','One example is a one-sheeted hyperboloid along x. '+r'\[y^2+z^2-x^2=1.\]'));graph(32,lambda u,v:(sinh(u),cosh(u)*cos(v),cosh(u)*sin(v)),(-1.5,1.5),(0,2*pi),'y²+z²-x²=1')
add(45,('원뿔과 원기둥 사이의 영역','Region between a cone and a cylinder'),('곡면 '+r'\(z=\sqrt{x^2+y^2},\ x^2+y^2=1,\ 1\le z\le2\)'+'로 둘러싸인 영역을 그려라.','Sketch the region bounded by '+r'\(z=\sqrt{x^2+y^2},\ x^2+y^2=1,\ 1\le z\le2\)'+'.'),fs(r'r=\sqrt{x^2+y^2},\quad r=1\text{ and }r=z',r'1\le z\le2,\quad1\le r\le z,\quad0\le\theta\le2\pi'),('각 높이의 단면이 안쪽 반지름 1, 바깥 반지름 z인 고리이다.','Each horizontal section is an annulus of inner radius 1 and outer radius z.'));graph(45,[lambda u,v:(u*cos(v),u*sin(v),u),lambda u,v:(cos(v),sin(v),u),lambda u,v:(u*cos(v),u*sin(v),2)],(1,2),(0,2*pi),'1 ≤ z ≤ 2; 1 ≤ r ≤ z')
add(46,('두 포물면 사이의 영역','Region between two paraboloids'),('다음 두 포물면이 둘러싸는 영역을 그려라. '+r'\(z=x^2+y^2,\quad z=2-x^2-y^2\).','Sketch the region enclosed by '+r'\(z=x^2+y^2,\quad z=2-x^2-y^2\).'),fs(r'r^2=2-r^2\implies r=1,\ z=1',r'0\le r\le1,\quad r^2\le z\le2-r^2'),('두 포물면은 높이1의 단위원에서 만난다. 그 사이의 회전대칭 렌즈형 입체이다.','The paraboloids meet on the unit circle at height1, enclosing a rotationally symmetric lens.'));graph(46,[lambda u,v:(u*cos(v),u*sin(v),u*u),lambda u,v:(u*cos(v),u*sin(v),2-u*u)],(0,1),(0,2*pi),'r² ≤ z ≤ 2-r²')
add(47,('회전으로 만드는 포물면','Paraboloid of revolution'),('곡선 '+r'\(y=\sqrt x\)'+'을 x축 둘레로 회전한 곡면의 식을 구하라.','Find the surface obtained by rotating '+r'\(y=\sqrt x\)'+' about x.'),fs(r'r=\sqrt{y^2+z^2}=\sqrt x',r'r^2=x'),same(r'\[x=y^2+z^2\quad(x\ge0).\]'))
add(48,('회전으로 만드는 원뿔','Cone of revolution'),('직선 '+r'\(z=2y\)'+'를 z축 둘레로 회전한 곡면의 식을 구하라.','Rotate the line '+r'\(z=2y\)'+' about z and find the surface equation.'),fs(r'z^2=4y^2,\quad y^2\longrightarrow x^2+y^2'),same(r'\[z^2=4(x^2+y^2).\]'))
add(49,('초점과 준평면','Focus and directrix plane'),('점 (-1,0,0)과 평면 x=1까지의 거리가 같은 점들의 곡면을 구하고 분류하라.','Find and classify the locus equidistant from (-1,0,0) and the plane x=1.'),fs(r'\sqrt{(x+1)^2+y^2+z^2}=|x-1|',r'(x+1)^2+y^2+z^2=(x-1)^2'),('음의 x방향 원포물면. '+r'\[y^2+z^2=-4x.\]','Circular paraboloid opening in negative x. '+r'\[y^2+z^2=-4x.\]'))
add(50,('거리비로 정하는 곡면','Surface defined by a distance ratio'),('x축까지의 거리가 yz평면까지 거리의 두 배인 점들의 곡면을 구하고 분류하라.','Find and classify points whose distance to the x-axis is twice their distance to the yz-plane.'),fs(r'd(P,x\text{-axis})=\sqrt{y^2+z^2},\quad d(P,yz\text{-plane})=|x|',r'\sqrt{y^2+z^2}=2|x|'),('x축 원뿔. '+r'\[y^2+z^2=4x^2.\]','Circular cone along x. '+r'\[y^2+z^2=4x^2.\]'))
add(51,('지구 타원면 모형','An ellipsoid model of Earth'),('교재가 제시한 극반지름 6356.523km, 적도반지름 6378.137km로 (a) 타원면 방정식을 구하고 (b) z=k인 위도선, (c) y=mx인 자오선의 모양을 설명하라.','Using the textbook’s polar radius6356.523km and equatorial radius6378.137km, find (a) the ellipsoid equation; describe (b) latitude traces z=k and (c) meridian traces y=mx.'),fs(r'a=6378.137,\quad c=6356.523',r'(a)\ (x^2+y^2)/a^2+z^2/c^2=1',r'(b)\ x^2+y^2=a^2(1-k^2/c^2)',r'(c)\ (1+m^2)x^2/a^2+z^2/c^2=1'),('(a) 위 타원면 식. (b) 원(극에서 점). (c) 타원. 수치는 교재에서 주어진 값을 그대로 사용했다.','(a) The displayed ellipsoid. (b) Circles, degenerating to points at the poles. (c) Ellipses. The constants are exactly those supplied by the textbook.'),['a','b','c'])
add(52,('냉각탑의 쌍곡면 모형','Hyperboloid model of a cooling tower'),('밑면 지름280m, 밑면에서500m 위의 최소지름200m인 일엽쌍곡면 냉각탑의 식을 구하라.','Model a one-sheeted hyperboloid cooling tower with base diameter280m and minimum diameter200m at height500m above the base.'),fs(r'\frac{x^2+y^2}{100^2}-\frac{(z-500)^2}{c^2}=1',r'\frac{140^2}{100^2}-\frac{500^2}{c^2}=1\implies c^2=\frac{781250}{3}'),same(r'\[\frac{x^2+y^2}{10000}-\frac{3(z-500)^2}{781250}=1,\quad z\ge0.\]'),check=('z=0에서 반지름140, z=500에서 최소반지름100이 복원된다.','At z=0 the radius is140; at z=500 the minimum radius is100.'))
add(53,('직선으로 생성되는 안장곡면','Rulings on a hyperbolic paraboloid'),('점 (a,b,c)가 '+r'\(z=y^2-x^2\)'+' 위에 있을 때 두 직선 '+r'\((x,y,z)=(a+t,b+t,c+2(b-a)t)\)'+'과 '+r'\((x,y,z)=(a+t,b-t,c-2(b+a)t)\)'+'이 곡면 위에 있음을 보이라.','For (a,b,c) on '+r'\(z=y^2-x^2\)'+' show the lines '+r'\((x,y,z)=(a+t,b+t,c+2(b-a)t)\)'+' and '+r'\((x,y,z)=(a+t,b-t,c-2(b+a)t)\)'+' lie entirely on the surface.'),fs(r'c=b^2-a^2',r'(b+t)^2-(a+t)^2=b^2-a^2+2(b-a)t=c+2(b-a)t',r'(b-t)^2-(a+t)^2=b^2-a^2-2(b+a)t=c-2(b+a)t'),('모든 실수 t에 대해 곡면 방정식을 만족하므로 두 직선이 모두 곡면에 포함된다.','Both parametrizations satisfy the surface equation for every real t, so both lines lie on it.'))
add(54,('교선이 놓인 평면','A plane containing an intersection curve'),('다음 두 곡면의 교선이 평면에 놓임을 보이라. '+r'\(x^2+2y^2-z^2+3x=1,\quad2x^2+4y^2-2z^2-5y=0\).','Show the intersection of '+r'\(x^2+2y^2-z^2+3x=1,\quad2x^2+4y^2-2z^2-5y=0\)'+' lies in a plane.'),[('첫 방정식을 두 배하여 둘째 방정식에서 빼면 모든 이차항이 소거된다.','Subtract twice the first equation from the second; every quadratic term cancels.')]+fs(r'-6x-5y=-2'),same(r'\[6x+5y=2.\]'))
add(55,('교선과 타원 투영','Intersection and elliptic projection'),('두 곡면 '+r'\(z=x^2+y^2,\ z=1-y^2\)'+'을 '+r'\(|x|,|y|\le1.2\)'+'에서 함께 그리고 교선의 xy평면 투영이 타원임을 보이라.','Graph '+r'\(z=x^2+y^2,\ z=1-y^2\)'+' together for '+r'\(|x|,|y|\le1.2\)'+' and prove the xy-projection of their intersection is an ellipse.'),fs(r'x^2+y^2=1-y^2\implies x^2+2y^2=1',r'x=\cos t,\quad y=\sin t/\sqrt2,\quad z=1-\sin^2t/2'),same(r'\[x^2+2y^2=1\quad\text{(semiaxes }1,1/\sqrt2\text{)}.\]'));graph(55,[lambda u,v:(u,v,u*u+v*v),lambda u,v:(u,v,1-v*v)],(-1.2,1.2),(-1.2,1.2),'Blue/purple: paraboloid; orange/green: cylinder')
assert sorted(b.E)==list(range(1,56));b.save()
print('12.6:55 complete')
